import assert from 'node:assert/strict';
import { test } from 'node:test';

import { nearestCity } from '../locations';
import {
  isPincodeCityId,
  isPincodeQuery,
  isPlaceQuery,
  lookupPincode,
  nearestPincode,
  pincodeCityId,
  placesForPincode,
  searchPlaces,
  snapToNearestLocation,
  toDevanagariDigits,
  toPincodeLocation,
} from '../pincodes';
import { STATE_LENS } from '../lensRegistry';
import pincodeData from '../pincodeData.json';
import pincodeOffices from '../pincodeOffices.json';

// Generated by `scripts/build-pincodes.mjs`; see that file for provenance and gates.
const INDIA = { latMin: 6.5, latMax: 37.6, lngMin: 68.0, lngMax: 97.5 };
const STRIDE = 6;

function kmBetween(lat1: number, lng1: number, lat2: number, lng2: number): number {
  const x = (lng2 - lng1) * Math.cos((((lat1 + lat2) / 2) * Math.PI) / 180);
  return Math.hypot(lat2 - lat1, x) * 111.2;
}

test('pincode table: shape matches what pincodes.ts assumes', () => {
  assert.equal(pincodeData.format, 2, 'format bump must be mirrored in pincodes.ts');
  assert.equal(pincodeData.stride, STRIDE);
  assert.equal(pincodeData.rows.length, pincodeData.count * STRIDE, 'flat array is count × stride');
  assert.ok(pincodeData.count > 19500, `expected 19.5k+ pincodes, got ${pincodeData.count}`);
  assert.equal(pincodeData.states.length, pincodeData.statesEn.length);
  assert.equal(pincodeData.states.length, pincodeData.statesHi.length);
});

test('office table: aligned with the pincode table, one kind per name, no separator inside a name', () => {
  assert.equal(pincodeOffices.format, pincodeData.format);
  assert.equal(pincodeOffices.pincodeCount, pincodeData.count, 'perPincode indexes pincodeData rows');
  assert.equal(pincodeOffices.perPincode.length, pincodeData.count);
  const names = pincodeOffices.names.split('|');
  assert.equal(names.length, pincodeOffices.count);
  assert.equal(pincodeOffices.kinds.length, pincodeOffices.count);
  assert.equal(pincodeOffices.perPincode.reduce((a, b) => a + b, 0), pincodeOffices.count);
  assert.ok(pincodeOffices.count > 160000, `expected 160k+ office names, got ${pincodeOffices.count}`);
  assert.ok(/^[HSB]+$/.test(pincodeOffices.kinds), 'kinds are H/S/B only');
  for (const [i, n] of pincodeOffices.perPincode.entries()) {
    assert.ok(n > 0, `pincode row ${i} has no office name — nothing to find it by`);
  }
  // `pincodes.ts` searches a lower-cased copy and reuses its offsets on the original —
  // only sound if lower-casing never changes a length, i.e. the names are ASCII.
  assert.ok(/^[\x20-\x7e]*$/.test(pincodeOffices.names), 'names must be printable ASCII');
  for (const name of names) assert.ok(name.trim().length >= 2 && name === name.trim(), `bad name "${name}"`);
});

test('pincode table: ascending order (binary search depends on it) and in-India coordinates', () => {
  let previous = -1;
  for (let row = 0; row < pincodeData.count; row += 1) {
    const at = row * STRIDE;
    const pin = pincodeData.rows[at];
    assert.ok(pin > previous, `pincodes must strictly ascend; ${pin} followed ${previous}`);
    previous = pin;

    const lat = pincodeData.rows[at + 1] / 1e4;
    const lng = pincodeData.rows[at + 2] / 1e4;
    assert.ok(pincodeData.districts[pincodeData.rows[at + 3]] !== undefined, `pincode ${pin} has no district`);
    assert.ok(pincodeData.statesEn[pincodeData.rows[at + 4]] !== undefined, `pincode ${pin} has no state`);
    assert.ok(pin < 900000, `${pin}: army/field post codes are not places`);
    assert.ok(
      lat >= INDIA.latMin && lat <= INDIA.latMax && lng >= INDIA.lngMin && lng <= INDIA.lngMax,
      `pincode ${pin} at (${lat}, ${lng}) is outside India`
    );
  }
});

test('pincode table: every state carries a Devanagari name', () => {
  for (const [index, hi] of pincodeData.statesHi.entries()) {
    assert.ok(hi.length > 0 && /[ऀ-ॿ]/.test(hi), `${pincodeData.statesEn[index]} lacks a Devanagari name`);
  }
});

test('isPincodeQuery accepts only a 6-digit code that does not start with 0', () => {
  assert.equal(isPincodeQuery('416001'), true);
  assert.equal(isPincodeQuery('  416001  '), true, 'trims');
  assert.equal(isPincodeQuery('41600'), false, 'too short');
  assert.equal(isPincodeQuery('4160011'), false, 'too long');
  assert.equal(isPincodeQuery('016001'), false, 'no Indian pincode begins with 0');
  assert.equal(isPincodeQuery('kolhapur'), false);
  assert.equal(isPincodeQuery(''), false);
});

test('lookupPincode resolves Kolhapur — the case the city list could not serve', () => {
  const entry = lookupPincode('416001');
  assert.ok(entry, '416001 must resolve');
  assert.equal(entry.pincode, '416001');
  assert.equal(entry.districtEn, 'Kolhapur');
  assert.equal(entry.stateEn, 'Maharashtra');
  assert.equal(entry.stateHi, 'महाराष्ट्र');
  // Roughly the city; the source geocoder sits ~19 km SW of the Mahalakshmi temple.
  assert.ok(Math.abs(entry.latitude - 16.7) < 0.3, `lat ${entry.latitude}`);
  assert.ok(Math.abs(entry.longitude - 74.24) < 0.3, `lng ${entry.longitude}`);
});

test('lookupPincode spot-checks across the country', () => {
  const cases: [string, string, string][] = [
    ['110001', 'New Delhi', 'Delhi'],
    ['400001', 'Mumbai', 'Maharashtra'],
    ['560001', 'Bengaluru Urban', 'Karnataka'],
    ['456001', 'Ujjain', 'Madhya Pradesh'],
    ['781001', 'Kamrup Metro', 'Assam'],
    ['194101', 'Leh Ladakh', 'Ladakh'],
    ['744101', 'South Andamans', 'Andaman and Nicobar Islands'],
    ['682551', 'Lakshadweep District', 'Lakshadweep'],
    // Mahe is Puducherry inside Kerala's sorting district — the enclave exemption.
    ['673310', 'Mahe', 'Puducherry'],
  ];
  for (const [pin, district, state] of cases) {
    const entry = lookupPincode(pin);
    assert.ok(entry, `${pin} must resolve`);
    assert.equal(entry.stateEn, state, `${pin} state`);
    assert.equal(entry.districtEn, district, `${pin} district`);
  }
});

test('coordinates land where the place is — each case is a source error the generator repairs', () => {
  // [pincode, true lat, true lng, km tolerance, what the raw source got wrong]
  const cases: [string, number, number, number, string][] = [
    ['700001', 22.5726, 88.3479, 5, 'seven offices typed 22°34′ as 22.34 — 30 km into the Hooghly'],
    ['824231', 24.6961, 84.9869, 10, "Gaya offices snapped onto Aurangabad, MAHARASHTRA (same-named district)"],
    ['276001', 26.0739, 83.1859, 10, 'Azamgarh offices snapped onto a point near Bengaluru'],
    ['391120', 21.9332, 73.5319, 15, 'Tilakwada: 20 offices share latitude 15.5934 (Goa)'],
    ['125121', 29.3687, 75.9052, 10, 'Barwala (Hisar): 18 offices on one point 170 km west'],
    ['110072', 28.6526, 76.9565, 10, "CRPF Jharoda Kalan's sub office reads 77.96° for 76.96°"],
    ['345001', 26.9157, 70.9083, 10, 'Jaisalmer: town offices must outvote 150 km of border villages'],
    ['416001', 16.7050, 74.2433, 10, 'the old geocoder put Kolhapur 19 km south-west'],
    ['190001', 34.0837, 74.7973, 5, 'Srinagar: absent from the old geocoder entirely'],
    ['194101', 34.1526, 77.5771, 10, 'Leh: absent from the old geocoder entirely'],
  ];
  for (const [pin, lat, lng, tolerance, why] of cases) {
    const entry = lookupPincode(pin);
    assert.ok(entry, `${pin} must resolve`);
    const off = kmBetween(lat, lng, entry.latitude, entry.longitude);
    assert.ok(off <= tolerance, `${pin} is ${off.toFixed(0)} km off (tolerance ${tolerance}) — ${why}`);
  }
});

test('misfiled states are repaired: Agartala is not in Telangana', () => {
  const agartala = lookupPincode('799001')!;
  assert.equal(agartala.stateEn, 'Tripura');
  assert.equal(agartala.stateHi, 'त्रिपुरा');
});

test('state names are the ones lensRegistry keys on', () => {
  // `lensesForStoredLabel` reads the state back off a stored `pin-` label. The previous
  // dataset spelled "Jammu & Kashmir" and so seeded nothing for any J&K pincode.
  for (const stateEn of pincodeData.statesEn) {
    assert.ok(!stateEn.includes('&'), `${stateEn}: spell states with "and"`);
  }
  for (const key of Object.keys(STATE_LENS)) {
    assert.ok(
      pincodeData.statesEn.some((s) => s.toLowerCase() === key),
      `STATE_LENS key "${key}" matches no state in the table`
    );
  }
});

test('lookupPincode returns null for malformed and unknown codes', () => {
  assert.equal(lookupPincode('41600'), null);
  assert.equal(lookupPincode('abcdef'), null);
  assert.equal(lookupPincode(''), null);
  // Well-formed but not a real pincode — the 9xxxxx range is Army Post Office, absent here.
  assert.equal(lookupPincode('999999'), null);
});

test('toDevanagariDigits converts digits and leaves other characters alone', () => {
  assert.equal(toDevanagariDigits('416001'), '४१६००१');
  assert.equal(toDevanagariDigits('110001'), '११०००१');
  assert.equal(toDevanagariDigits('· x'), '· x');
});

test('pincode city ids are stable, prefixed, and recognised', () => {
  assert.equal(pincodeCityId('416001'), 'pin-416001');
  assert.equal(isPincodeCityId('pin-416001'), true);
  assert.equal(isPincodeCityId('pin-41600'), false);
  assert.equal(isPincodeCityId('pin-016001'), false);
  assert.equal(isPincodeCityId('ujjain'), false);
  assert.equal(isPincodeCityId('rj-mount-abu'), false);
});

test('toPincodeLocation keeps a picked place name in English and the state at the tail', () => {
  const entry = lookupPincode('416001')!;
  const location = toPincodeLocation(entry, 'pincode', 'Shahupuri');
  assert.equal(location.cityId, 'pin-416001', 'a place IS its pincode — same id, same coordinate');
  assert.equal(location.labelEn, 'Shahupuri · 416001, Maharashtra');
  assert.equal(location.labelHi, '४१६००१ · महाराष्ट्र', 'no invented Devanagari spelling');
  assert.equal(location.latitude, entry.latitude);
});

test('toPincodeLocation labels in both scripts and keeps its source', () => {
  const entry = lookupPincode('416001')!;
  const location = toPincodeLocation(entry, 'pincode');
  assert.equal(location.cityId, 'pin-416001');
  assert.equal(location.labelEn, '416001 · Kolhapur, Maharashtra');
  assert.equal(location.labelHi, '४१६००१ · महाराष्ट्र');
  assert.ok(/[ऀ-ॿ]/.test(location.labelHi), 'Hindi label must be Devanagari so gu/kn transliteration works');
  assert.equal(location.source, 'pincode');
  assert.equal(location.latitude, entry.latitude);
  assert.equal(location.elevation, entry.elevation);
});

test('nearestPincode beats nearestCity where the city list is sparse', () => {
  // The Mahalakshmi temple, Kolhapur. Before the pincode tier this GPS fix snapped to
  // Panaji — a different state, ~135 km away, and Goa's sunrise.
  const lat = 16.7;
  const lng = 74.233;
  assert.equal(nearestCity(lat, lng).id, 'panaji', 'the old behaviour this tier replaces');

  const entry = nearestPincode(lat, lng);
  assert.ok(entry, 'a nearest pincode must exist');
  assert.equal(entry.stateEn, 'Maharashtra', 'must not cross into Goa');
  const km = Math.hypot((entry.latitude - lat) * 111, (entry.longitude - lng) * 111 * Math.cos((lat * Math.PI) / 180));
  assert.ok(km < 25, `nearest pincode should be close, was ${km.toFixed(0)} km`);
});

test('snapToNearestLocation returns a gps-sourced location', () => {
  const location = snapToNearestLocation(16.7, 74.233);
  assert.equal(location.source, 'gps');
  assert.ok(isPincodeCityId(location.cityId), `expected a pincode id, got ${location.cityId}`);
  assert.ok(location.labelEn.includes('Maharashtra'));
});

test('snapToNearestLocation keeps the CITY when the city is the closer answer', () => {
  // The guard this tier shipped with. Under the first geocoder, Srinagar's "nearest"
  // pincode was 156 km away in Doda (1 of 207 J&K pincodes was geocoded) while the
  // bundled city sat on the fix. Coverage is complete now, but the rule stands: a fix ON a
  // bundled city stays that city — ties go to the bilingual name.
  const location = snapToNearestLocation(34.0837, 74.7973);
  assert.equal(location.cityId, 'srinagar', `expected the bundled city, got ${location.cityId}`);
  assert.equal(location.source, 'gps');

  // Ziro, Arunachal Pradesh, has no bundled city; its own pincode is the answer.
  const ziro = snapToNearestLocation(27.63, 93.83);
  assert.ok(isPincodeCityId(ziro.cityId), `expected a pincode, got ${ziro.cityId}`);
});

test('nearestPincode now finds Srinagar itself, not a pincode in Doda', () => {
  const entry = nearestPincode(34.0837, 74.7973);
  assert.ok(entry, 'must resolve');
  assert.equal(entry.stateEn, 'Jammu and Kashmir');
  assert.ok(kmBetween(34.0837, 74.7973, entry.latitude, entry.longitude) < 5, 'J&K is fully covered now');
});

test('isPlaceQuery wants three Latin letters', () => {
  assert.equal(isPlaceQuery('kol'), true);
  assert.equal(isPlaceQuery('  Ko  '), false, 'two letters match a third of India');
  assert.equal(isPlaceQuery('कोल्हापुर'), false, 'the directory is Latin-only');
  assert.equal(isPlaceQuery('416'), false, 'digits are a pincode in progress, not a name');
});

test('searchPlaces finds a village the city list never had', () => {
  const [first] = searchPlaces('Kothimir');
  assert.ok(first, 'a branch office in Kumuram Bheem Asifabad must be findable by name');
  assert.equal(first.name, 'Kothimir');
  assert.equal(first.kind, 'branch');
  assert.equal(first.entry.pincode, '504273');
  assert.equal(first.entry.stateEn, 'Telangana');
});

test('searchPlaces is case- and space-insensitive', () => {
  assert.deepEqual(
    searchPlaces('  SHAHU   puri ').map((p) => p.entry.pincode),
    searchPlaces('shahu puri').map((p) => p.entry.pincode)
  );
  assert.equal(searchPlaces('shahupuri')[0].entry.pincode, '416001');
});

test('searchPlaces ranks towns above same-named villages, and prefixes above substrings', () => {
  // Six villages are called exactly "Srinagar"; the GPO in Kashmir must still lead.
  const srinagar = searchPlaces('srinagar');
  assert.equal(srinagar[0].name, 'Srinagar GPO');
  assert.equal(srinagar[0].entry.stateEn, 'Jammu and Kashmir');

  const rampur = searchPlaces('rampur');
  assert.equal(rampur[0].name, 'Rampur');
  assert.equal(rampur[0].kind, 'head');
  const firstSubstring = rampur.findIndex((p) => !p.name.toLowerCase().split(/[ (\-./]/).some((w) => w.startsWith('rampur')));
  const lastPrefix = rampur.map((p) => p.name.toLowerCase().startsWith('rampur')).lastIndexOf(true);
  assert.ok(firstSubstring === -1 || firstSubstring > lastPrefix, 'a substring hit never outranks a prefix hit');
});

test('searchPlaces honours its limit and returns nothing for a non-name', () => {
  assert.equal(searchPlaces('ram', 10).length, 10);
  assert.deepEqual(searchPlaces('ra'), []);
  assert.deepEqual(searchPlaces('zzqqxx'), []);
  assert.deepEqual(searchPlaces('a|b|c'), [], 'the separator never matches across names');
});

test('placesForPincode lists what a code serves, towns first', () => {
  const places = placesForPincode('781001');
  assert.equal(places[0], 'Guwahati GPO', 'head office first');
  assert.ok(places.includes('Fancy Bazar'));
  assert.deepEqual(placesForPincode('999999'), []);
});
